#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    char *input = argv[1];
    size_t len = strlen(input);
    if (len == 0) {
        puts("INVALID_INPUT");
        return 0;
    }
    // validate input contains only '0' or '1'
    for (size_t i = 0; i < len; ++i) {
        if (input[i] != '0' && input[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }
    // copy to mutable tape
    char *tape = malloc(len + 1);
    if (!tape) return 1;
    memcpy(tape, input, len);
    tape[len] = '\0';

    int steps = 0;
    // simulate binary increment (right‑most bit first)
    ssize_t idx = (ssize_t)len - 1; // signed index
    while (idx >= 0 && tape[idx] == '1') {
        tape[idx] = '0';
        steps++;
        idx--;
    }
    if (idx >= 0) {
        // flip the first 0 to 1
        tape[idx] = '1';
        steps++;
        // output result
        printf("result=");
        for (size_t i = 0; i < len; ++i) {
            putchar(tape[i]);
        }
        printf(" steps=%d\n", steps);
    } else {
        // overflow – all bits were 1
        puts("OVERFLOW");
        printf(" steps=%d\n", steps);
    }
    free(tape);
    return 0;
}
